import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Avatar","description":"","frontmatter":{},"headers":[],"relativePath":"components/avatar.md","filePath":"components/avatar.md"}'),i={name:"components/avatar.md"};function n(d,a,h,s,l,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="avatar" tabindex="-1">Avatar <a class="header-anchor" href="#avatar" aria-label="Permalink to &quot;Avatar&quot;">​</a></h1><p>Avatar is the round mark of a person, with their initials.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it alone beside a name, or with <code>in</code> at the start of a list item or in a toolbar. It takes initials only. A thing that is not a person is a <a href="./tile">Tile</a> or a <a href="./thumbnail">Thumbnail</a>; the people who are here now are a <a href="./presence">Presence</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>initial</code></td><td>required</td><td>One or two characters</td></tr><tr><td><code>in</code></td><td><code>false</code></td><td>The small size, inside a list item or a toolbar</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A circle of <code>--kata-height-button-sm</code>, or of <code>--kata-height-badge</code> with <code>in</code>. The surface is the opaque fill color, so that overlapping avatars do not show through; a container gives a person a color by setting <code>--kata-color-fill</code>. The initials are a caption (a glyph with <code>in</code>) in the heavy weight, trimmed to their ink and centred.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/avatar/" title="Avatar" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/avatar/" target="_blank" rel="noopener">Avatar</a></figcaption></figure>',10)])])}const f=e(i,[["render",n]]);export{m as __pageData,f as default};
